    public static class BotLog
    {
        private static readonly object _lock = new();
        public static bool Enabled =>
            Environment.GetEnvironmentVariable("SOT_LOG") == "1";

        // Unique per process, so multiple bot instances running at once don't clobber each other's log.
        private static readonly string DefaultPath =
            $"deepsets_{DateTime.Now:yyyyMMdd_HHmmss}_{Process.GetCurrentProcess().Id}.log";

        private static string Path =>
            Environment.GetEnvironmentVariable("SOT_LOG_FILE") ?? DefaultPath;

        public static void Write(string msg)
        {
            if (!Enabled) return;
            lock (_lock)
            {
                File.AppendAllText(Path,
                    $"[{DateTime.Now:HH:mm:ss.fff}][t{Thread.CurrentThread.ManagedThreadId}] {msg}\n");
            }
        }
    }

