        public static float[] GetCardEffects(CardId cardId)
        {
            if (Effects.TryGetValue(cardId, out float[] effects))
                return effects;

            // Return a safe zero-vector if a card is somehow missing
            return new float[76];
        }
    }

    // This encoding must exactly match the format the model was trained on;
    // the two are produced by separate code and have to be kept in sync by hand.
    public static class FeatureExtractor
    {
        public const int NODE_DIM = 99;
        public const int GLOBAL_DIM = 19;

        // Competition-only, favour-eligible patrons for the global vector's
        // favour block. TREASURY is excluded but still appears in the node vector's
        // 7-dim Deck one-hot below.
        private static readonly PatronId[] PatronOrder = new[]
        {
            PatronId.ANSEI, PatronId.DUKE_OF_CROWS, PatronId.RAJHIN,
            PatronId.ORGNUM, PatronId.PELIN, PatronId.SAINT_ALESSIA
        };

        // Explicit live-patron-id -> one-hot-slot mapping for the node vector's
        // Deck block. Anything not in this map (PSIJIC=3, HLAALU=5, RED_EAGLE=7,
        // or any other value) encodes as all-zero, deliberately, since those
        // decks can never appear in a competition game.
        private static readonly Dictionary<int, int> DeckIdToSlot = new Dictionary<int, int>
        {
            { 0, 0 }, // ANSEI
            { 1, 1 }, // DUKE_OF_CROWS
            { 2, 2 }, // RAJHIN
            { 4, 3 }, // ORGNUM
            { 6, 4 }, // PELIN
            { 8, 5 }, // TREASURY
            { 9, 6 }, // SAINT_ALESSIA
        };

        private const float LOC_TAVERN         = 0.0f;
        private const float LOC_MY_HAND        = 1.0f;
        private const float LOC_MY_PLAYED      = 2.0f;
        private const float LOC_MY_COOLDOWN    = 3.0f;
        private const float LOC_MY_DRAW        = 4.0f;
        private const float LOC_MY_AGENT       = 5.0f;
        private const float LOC_ENEMY_AGENT    = 6.0f;
        private const float LOC_ENEMY_COOLDOWN = 7.0f;
        private const float LOC_ENEMY_UNSEEN   = 8.0f;

        /// Builds the node/global feature vectors for a live GameState.
        public static (float[,], long[], float[]) ParseState(GameState state, bool isTerminal = false)
        {
            var nodes = new List<float[]>();

            foreach (var c in state.TavernAvailableCards) nodes.Add(EncodeCard(c, LOC_TAVERN));
            foreach (var c in state.CurrentPlayer.Hand) nodes.Add(EncodeCard(c, LOC_MY_HAND));
            foreach (var c in state.CurrentPlayer.Played) nodes.Add(EncodeCard(c, LOC_MY_PLAYED));
            foreach (var c in state.CurrentPlayer.CooldownPile) nodes.Add(EncodeCard(c, LOC_MY_COOLDOWN));
            foreach (var c in state.CurrentPlayer.DrawPile) nodes.Add(EncodeCard(c, LOC_MY_DRAW));
            foreach (var a in state.CurrentPlayer.Agents) nodes.Add(EncodeCard(a.RepresentingCard, LOC_MY_AGENT, a.CurrentHp));
            foreach (var a in state.EnemyPlayer.Agents) nodes.Add(EncodeCard(a.RepresentingCard, LOC_ENEMY_AGENT, a.CurrentHp));
            foreach (var c in state.EnemyPlayer.CooldownPile) nodes.Add(EncodeCard(c, LOC_ENEMY_COOLDOWN));
            foreach (var c in state.EnemyPlayer.HandAndDraw) nodes.Add(EncodeCard(c, LOC_ENEMY_UNSEEN));

            int numNodes = nodes.Count;
            if (numNodes == 0)
            {
                numNodes = 1;
                nodes.Add(EncodeCard(null, 0.0f));
            }

            float[,] nodeFeatures = new float[numNodes, NODE_DIM];
            long[] batchMapping = new long[numNodes];

            for (int i = 0; i < numNodes; i++)
            {
                for (int j = 0; j < NODE_DIM; j++)
                {
                    nodeFeatures[i, j] = nodes[i][j];
                }
                batchMapping[i] = 0;
            }

            float[] globalFeatures = EncodeGlobalContext(state, isTerminal);

            return (nodeFeatures, batchMapping, globalFeatures);
        }

        /// Overload for SeededGameState (used by MCTS nodes).
        public static (float[,], long[], float[]) ParseState(SeededGameState state, bool isTerminal = false)
        {
            var nodes = new List<float[]>();

            foreach (var c in state.TavernAvailableCards) nodes.Add(EncodeCard(c, LOC_TAVERN));
            foreach (var c in state.CurrentPlayer.Hand) nodes.Add(EncodeCard(c, LOC_MY_HAND));
            foreach (var c in state.CurrentPlayer.Played) nodes.Add(EncodeCard(c, LOC_MY_PLAYED));
            foreach (var c in state.CurrentPlayer.CooldownPile) nodes.Add(EncodeCard(c, LOC_MY_COOLDOWN));
            foreach (var c in state.CurrentPlayer.DrawPile) nodes.Add(EncodeCard(c, LOC_MY_DRAW));
            foreach (var a in state.CurrentPlayer.Agents) nodes.Add(EncodeCard(a.RepresentingCard, LOC_MY_AGENT, a.CurrentHp));
            foreach (var a in state.EnemyPlayer.Agents) nodes.Add(EncodeCard(a.RepresentingCard, LOC_ENEMY_AGENT, a.CurrentHp));
            foreach (var c in state.EnemyPlayer.CooldownPile) nodes.Add(EncodeCard(c, LOC_ENEMY_COOLDOWN));
            // SeededGameState.EnemyPlayer is a full SerializedPlayer with separate
            // Hand/DrawPile (no HandAndDraw property), so they're concatenated here
            // to encode the same set as the GameState overload above.
            foreach (var c in state.EnemyPlayer.Hand) nodes.Add(EncodeCard(c, LOC_ENEMY_UNSEEN));
            foreach (var c in state.EnemyPlayer.DrawPile) nodes.Add(EncodeCard(c, LOC_ENEMY_UNSEEN));

            int numNodes = nodes.Count;
            if (numNodes == 0)
            {
                numNodes = 1;
                nodes.Add(EncodeCard(null, 0.0f));
            }

            float[,] nodeFeatures = new float[numNodes, NODE_DIM];
            long[] batchMapping = new long[numNodes];

            for (int i = 0; i < numNodes; i++)
            {
                for (int j = 0; j < NODE_DIM; j++)
                {
                    nodeFeatures[i, j] = nodes[i][j];
                }
                batchMapping[i] = 0;
            }

            float[] globalFeatures = EncodeGlobalContext(state, isTerminal);

            return (nodeFeatures, batchMapping, globalFeatures);
        }

        /// Translates a single Card into the NODE_DIM-dimensional array.
        private static float[] EncodeCard(Card? card, float locationId, int currentHp = -1)
        {
            float[] vector = new float[NODE_DIM];

            if (card == null) return vector;

            // [Indices 0-6] Deck (7 dims, one-hot over the live competition
            // patrons only, anything else, e.g. PSIJIC/HLAALU/RED_EAGLE,
            // stays all-zero since it can never appear in a competition game).
            int deck = (int)card.Deck;
            if (DeckIdToSlot.TryGetValue(deck, out int deckSlot)) vector[deckSlot] = 1.0f;

            // [Index 7] Cost (1 dim, Float, normalized)
            vector[7] = card.Cost / 10.0f;

            // [Indices 8-11] Type (4 dims, One-Hot)
            int type = (int)card.Type;
            if (type >= 0 && type <= 3) vector[8 + type] = 1.0f;

            // [Index 12] HP (normalized)
            vector[12] = (currentHp != -1 ? currentHp : card.HP) / 40.0f;

            // [Index 13] Taunt
            vector[13] = card.Taunt ? 1.0f : 0.0f;

            // [Indices 14-89] Card Effects (76 dims, Float, normalized)
            float[] effectsList = CardDatabase.GetCardEffects(card.CommonId);
            for (int i = 0; i < 76; i++)
            {
                vector[14 + i] = effectsList[i] / 5.0f;
            }

            // [Indices 90-98] Location (9 dims, One-Hot)
            int locId = (int)locationId;
            if (locId >= 0 && locId <= 8) vector[90 + locId] = 1.0f;

            return vector;
        }

        /// Builds the global (non-card) feature vector for a live GameState.
        private static float[] EncodeGlobalContext(GameState state, bool isTerminal = false)
        {
            float[] vector = new float[GLOBAL_DIM];

            // [Indices 0-6] Player Resources
            vector[0] = state.CurrentPlayer.Coins / 10.0f;
            vector[1] = state.CurrentPlayer.Power / 10.0f;
            vector[2] = state.CurrentPlayer.Prestige / 40.0f;
            vector[3] = state.CurrentPlayer.PatronCalls;

            vector[4] = state.EnemyPlayer.Coins / 10.0f;
            vector[5] = state.EnemyPlayer.Power / 10.0f;
            vector[6] = state.EnemyPlayer.Prestige / 40.0f;

            // [Indices 7-12] Patron favour, resolved relative to CurrentPlayer.PlayerID
            // rather than a fixed player slot, so the encoding is correct for
            // whichever side is asking.
            for (int i = 0; i < PatronOrder.Length; i++)
            {
                PatronId currentPatron = PatronOrder[i];
                if (state.PatronStates.All.TryGetValue(currentPatron, out PlayerEnum favor))
                {
                    if (favor == state.CurrentPlayer.PlayerID) vector[7 + i] = 1.0f;
                    else if (favor == state.EnemyPlayer.PlayerID) vector[7 + i] = -1.0f;
                    else vector[7 + i] = 0.0f; // Neutral
                }
                else
                {
                    vector[7 + i] = -2.0f; // Not drafted this match
                }
            }

            float myPrestige = state.CurrentPlayer.Prestige;
            float enemyPrestige = state.EnemyPlayer.Prestige;

            // [Index 13] Prestige clock
            vector[13] = Math.Min(Math.Max(myPrestige, enemyPrestige) / 40.0f, 1.2f);

            // [Index 14] Prestige differential
            vector[14] = (myPrestige - enemyPrestige) / 40.0f;

            // [Index 15] My deck size (hand + played + cooldown + draw, NOT agents)
            vector[15] = (state.CurrentPlayer.Hand.Count + state.CurrentPlayer.Played.Count +
                          state.CurrentPlayer.CooldownPile.Count + state.CurrentPlayer.DrawPile.Count) / 30.0f;

            // [Index 16] Enemy known deck size (HandAndDraw + cooldown, NOT agents)
            vector[16] = (state.EnemyPlayer.HandAndDraw.Count + state.EnemyPlayer.CooldownPile.Count) / 30.0f;

            // [Index 17-18] Agent counts
            vector[17] = state.CurrentPlayer.Agents.Count / 5.0f;
            vector[18] = state.EnemyPlayer.Agents.Count / 5.0f;

            return vector;
        }

        /// Overload for SeededGameState (used by MCTS nodes).
        private static float[] EncodeGlobalContext(SeededGameState state, bool isTerminal = false)
        {
            float[] vector = new float[GLOBAL_DIM];

            vector[0] = state.CurrentPlayer.Coins / 10.0f;
            vector[1] = state.CurrentPlayer.Power / 10.0f;
            vector[2] = state.CurrentPlayer.Prestige / 40.0f;
            vector[3] = state.CurrentPlayer.PatronCalls;

            vector[4] = state.EnemyPlayer.Coins / 10.0f;
            vector[5] = state.EnemyPlayer.Power / 10.0f;
            vector[6] = state.EnemyPlayer.Prestige / 40.0f;

            for (int i = 0; i < PatronOrder.Length; i++)
            {
                PatronId currentPatron = PatronOrder[i];
                if (state.PatronStates.All.TryGetValue(currentPatron, out PlayerEnum favor))
                {
                    if (favor == state.CurrentPlayer.PlayerID) vector[7 + i] = 1.0f;
                    else if (favor == state.EnemyPlayer.PlayerID) vector[7 + i] = -1.0f;
                    else vector[7 + i] = 0.0f;
                }
                else
                {
                    vector[7 + i] = -2.0f;
                }
            }

            float myPrestige = state.CurrentPlayer.Prestige;
            float enemyPrestige = state.EnemyPlayer.Prestige;

            vector[13] = Math.Min(Math.Max(myPrestige, enemyPrestige) / 40.0f, 1.2f);
            vector[14] = (myPrestige - enemyPrestige) / 40.0f;

            vector[15] = (state.CurrentPlayer.Hand.Count + state.CurrentPlayer.Played.Count +
                          state.CurrentPlayer.CooldownPile.Count + state.CurrentPlayer.DrawPile.Count) / 30.0f;

            // SeededGameState.EnemyPlayer has no HandAndDraw; Hand + DrawPile
            // is the same set (see the node-vector overload above).
            vector[16] = (state.EnemyPlayer.Hand.Count + state.EnemyPlayer.DrawPile.Count +
                          state.EnemyPlayer.CooldownPile.Count) / 30.0f;

            vector[17] = state.CurrentPlayer.Agents.Count / 5.0f;
            vector[18] = state.EnemyPlayer.Agents.Count / 5.0f;

            return vector;
        }
    }

    public class ValueNetworkEvaluator : IDisposable
    {
        private readonly InferenceSession _session;

        public ValueNetworkEvaluator(string modelPath)
        {
            using (var opts = new SessionOptions())
            {
                opts.IntraOpNumThreads = 1;
                opts.InterOpNumThreads = 1;
                opts.ExecutionMode = ExecutionMode.ORT_SEQUENTIAL;

                _session = new InferenceSession(modelPath, opts);
            }
        }

        /// Evaluates a board state and returns the probability of winning (0.0 to 1.0)
        public float EvaluateBoardState(float[,] nodeFeatures, float[] globalFeatures)
        {
            int numNodes = nodeFeatures.GetLength(0);

            // ONNX's DenseTensor requires a flat array, not a 2D one.
            float[] flatNodes = new float[numNodes * FeatureExtractor.NODE_DIM];
            Buffer.BlockCopy(nodeFeatures, 0, flatNodes, 0, flatNodes.Length * sizeof(float));

            // Shapes must match the exported model's expected input shapes exactly.
            var nodeTensor = new DenseTensor<float>(flatNodes, new[] { numNodes, FeatureExtractor.NODE_DIM });
            var globalTensor = new DenseTensor<float>(globalFeatures, new[] { 1, FeatureExtractor.GLOBAL_DIM });

            var inputs = new List<NamedOnnxValue>
            {
                NamedOnnxValue.CreateFromTensor("node_features", nodeTensor),
                NamedOnnxValue.CreateFromTensor("global_features", globalTensor)
            };

            using IDisposableReadOnlyCollection<DisposableNamedOnnxValue> results = _session.Run(inputs);

            // The model outputs a raw logit, not a probability, so sigmoid is applied here.
            float rawLogit = results.First(r => r.Name == "win_probability").AsEnumerable<float>().First();
            float winProbability = 1.0f / (1.0f + (float)Math.Exp(-rawLogit));

            return winProbability;
        }

        public void Dispose()
        {
            // _session wraps a native OnnxRuntime handle that the GC won't reclaim on its own.
            _session?.Dispose();
        }
    }
}
